    """Mark each region containing an orthogonally adjacent pair of signal cells."""
    h, w = len(grid), len(grid[0])
    # Full-width/full-height uniform lines are panel separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
