    counts = {}
    for row in grid:
        for value in row:
            if value != divider:
                counts[value] = counts.get(value, 0) + 1
    # The background dominates each panel; the sparse other color is the signal.
    background = max(counts, key=counts.get)
    signal = min((v for v in counts if v != background), key=lambda v: counts[v])

    def regions(length, separators):
        result, start = [], 0
        for pos in separators:
            result.append((start, pos))
            start = pos + 1
        result.append((start, length))
        return result

    row_regions = regions(h, sep_rows)
